    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++; // Skip the backslash
            if (i < input.length()) {
                c = input.charAt(i);
                // Handle common escape sequences
                switch (c) {
                    case 'n':
                        output.append('\n');
                        break;
                    case 'r':
                        output.append('\r');
                        break;
                    case 't':
                        output.append('\t');
                        break;
                    case 'b':
                        output.append('\b');
                        break;
                    case 'f':
                        output.append('\f');
                        break;
                    case '\\':
                        output.append('\\');
                        break;
                    case '"':
                        output.append('"');
                        break;
                    case '\'':
                        output.append('\'');
                        break;
                    default:
                        output.append(c); // If not a recognized escape sequence, just append the character
