}

private int popType(final String descriptor, int index) {
    switch (descriptor.charAt(index)) {
        case 'B':
        case 'C':
        case 'I':
        case 'S':
        case 'Z':
            // These are single-word types
            index++;
            break;
        case 'D':
        case 'J':
            // These are double-word types
            index++;
            break;
        case 'L':
            // Object type, skip to the end of the class name
            index = descriptor.indexOf(';', index) + 1;
            break;
        case '[':
            // Array type, skip to the end of the array descriptor
            do {
                index++;
            } while (descriptor.charAt(index) == '[');
            // Now index points to the type of the array elements
            index = popType(descriptor, index);
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    return index;
}

